def _value(src):
    src = src.strip()
    if src in ('true','false'):
        return src == 'true'
    if src.startswith(('"', "'")):
        try:
            return ast.literal_eval(src)
        except Exception:
            return src[1:-1]
    if src.startswith('[') and src.endswith(']'):
        body = src[1:-1]
        vals=[]; start=0; quote=None; depth=0; esc=False
        for i,c in enumerate(body):
            if esc: esc=False; continue
            if c=='\\' and quote=='"': esc=True; continue
            if quote:
                if c==quote: quote=None
            elif c in ('"', "'"): quote=c
            elif c=='[': depth+=1
            elif c==']': depth-=1
            elif c==',' and depth==0:
                if body[start:i].strip(): vals.append(_value(body[start:i]))
                start=i+1
        if body[start:].strip(): vals.append(_value(body[start:]))
        return vals
    try:
        return int(src.replace('_',''), 0)
    except ValueError:
        try: return float(src.replace('_',''))
        except ValueError: return src


def parse_toml(text):
    """Parse the TOML subset used in project config files."""
    root={}; table=root
    for line_no,line in enumerate(text.splitlines(),1):
        # Strip comments outside quoted strings.
        quote=None; esc=False; cut=len(line)
        for i,c in enumerate(line):
            if esc: esc=False; continue
            if c=='\\' and quote=='"': esc=True; continue
            if quote:
                if c==quote: quote=None
            elif c in ('"', "'"): quote=c
            elif c=='#': cut=i; break
        line=line[:cut].strip()
        if not line: continue
        m=re.fullmatch(r'\[([^\]]+)\]',line)
        if m:
            table=root
            for part in m.group(1).split('.'):
                part=part.strip().strip('"\'')
                table=table.setdefault(part,{})
            continue
        # Find first equals outside strings.
        quote=None; pos=-1
        for i,c in enumerate(line):
            if c in ('"',"'"): quote = None if quote==c else (c if quote is None else quote)
            elif c=='=' and quote is None: pos=i; break
        if pos<1: raise ValueError(f"invalid TOML at line {line_no}")
        key=line[:pos].strip().strip('"\'')
        table[key]=_value(line[pos+1:])
    return root


def find_config(cwd=None, explicit=None, disabled=False):
    if disabled: return None
    if explicit:
        return os.path.abspath(os.path.join(cwd or os.getcwd(), explicit))
    here=os.path.abspath(cwd or os.getcwd())
    while True:
        p=os.path.join(here,'.cfv.toml')
        if os.path.isfile(p): return p
        parent=os.path.dirname(here)
        if parent==here: return None
        here=parent


def load_config(cwd=None, explicit=None, disabled=False):
    """Return (dict, path, error). error is a user-facing reason string."""
    path=find_config(cwd,explicit,disabled)
    if path is None: return {},None,None
    try:
        with open(path,encoding='utf-8') as f: cfg=parse_toml(f.read())
    except OSError as e:
        return {},path,f"reading config file: open {explicit or path}: {e.strerror}"
    except (UnicodeError,ValueError) as e:
        return {},path,f"config file {path}: {e}"
    err=validate_config(cfg,path)
    return (cfg if not err else {}),path,err


def validate_config(cfg,path='<config>'):
    unknown=set(cfg)-TOP_KEYS
    if unknown: return f'config file {path}: schema validation failed: (root): Additional property {sorted(unknown)[0]} is not allowed'
    for key in ('exclude-dirs','exclude-file-types','file-types','reporter','groupby'):
        if key in cfg and (not isinstance(cfg[key],list) or not all(isinstance(x,str) for x in cfg[key])):
            return f'config file {path}: schema validation failed: {key}: Invalid type. Expected: array, given: {type(cfg[key]).__name__}'
    if 'depth' in cfg and (not isinstance(cfg['depth'],int) or isinstance(cfg['depth'],bool) or cfg['depth']<0):
        return f'config file {path}: schema validation failed: depth: Must be greater than or equal to 0'
    for k in ('quiet','require-schema','no-schema','schemastore','globbing','gitignore'):
        if k in cfg and not isinstance(cfg[k],bool): return f'config file {path}: schema validation failed: {k}: Invalid type. Expected: boolean'
    for k in ('schema-map','type-map','validators'):
        if k in cfg and not isinstance(cfg[k],dict): return f'config file {path}: schema validation failed: {k}: Invalid type. Expected: object'
    v=cfg.get('validators',{})
    for typ,opts in v.items():
        if not isinstance(opts,dict): continue
        allowed={'csv':{'delimiter','comment','lazy-quotes'},'json':{'forbid-duplicate-keys'},'ini':{'forbid-duplicate-keys'}}.get(typ,set())
        extras=set(opts)-allowed
        if extras: return f'config file {path}: schema validation failed: validators.{typ}: Additional property {sorted(extras)[0]} is not allowed'
        if typ=='csv' and isinstance(opts.get('delimiter'),str) and len(opts['delimiter'])>2:
            return f'config file {path}: schema validation failed: validators.csv.delimiter: String length must be less than or equal to 2'
    return None
