def load_config(cwd=None, explicit=None, disabled=False):
    """Return (dict, path, error). error is a user-facing reason string."""
    path=find_config(cwd,explicit,disabled)
    if path is None: return {},None,None
    try:
        with open(path,encoding='utf-8') as f: cfg=parse_toml(f.read())
    except OSError as e:
        return {},path,f"reading config file: open {explicit or path}: {e.strerror}"
    except (UnicodeError,ValueError) as e:
        return {},path,f"config file {path}: {e}"
    err=validate_config(cfg,path)
    return (cfg if not err else {}),path,err


def validate_config(cfg,path='<config>'):
    unknown=set(cfg)-TOP_KEYS
    if unknown: return f'config file {path}: schema validation failed: (root): Additional property {sorted(unknown)[0]} is not allowed'
    for key in ('exclude-dirs','exclude-file-types','file-types','reporter','groupby'):
        if key in cfg and not isinstance(cfg[key],list):
            return f'config file {path}: schema validation failed: {key}: Invalid type. Expected: array, given: {_type_name(cfg[key])}'
        if key in cfg:
            for i,item in enumerate(cfg[key]):
                if not isinstance(item,str):
                    return f'config file {path}: schema validation failed: {key}.{i}: Invalid type. Expected: string, given: {_type_name(item)}'
    for key,allowed in {'groupby':['filetype','directory','pass-fail','error-type'],'reporter':['standard','json','junit','sarif','github']}.items():
        for i,value in enumerate(cfg.get(key,[])):
            if value not in allowed and not (key=='reporter' and ':' in value and value.split(':',1)[0] in allowed):
                vals=', '.join('\"'+x+'\"' for x in allowed)
                return f'config file {path}: schema validation failed: {key}.{i}: {key}.{i} must be one of the following: {vals}'
    if 'depth' in cfg and (not isinstance(cfg['depth'],int) or isinstance(cfg['depth'],bool)):
        kind='boolean' if isinstance(cfg['depth'],bool) else 'string' if isinstance(cfg['depth'],str) else 'number' if isinstance(cfg['depth'],float) else 'array' if isinstance(cfg['depth'],list) else 'object'
        return f'config file {path}: schema validation failed: depth: Invalid type. Expected: integer, given: {kind}'
    if 'depth' in cfg and cfg['depth']<0:
        return f'config file {path}: schema validation failed: depth: Must be greater than or equal to 0'
    for k in ('quiet','require-schema','no-schema','schemastore','globbing','gitignore'):
        if k in cfg and not isinstance(cfg[k],bool): return f'config file {path}: schema validation failed: {k}: Invalid type. Expected: boolean, given: {_type_name(cfg[k])}'
    for k in ('schema-map','type-map','validators'):
        if k in cfg and not isinstance(cfg[k],dict): return f'config file {path}: schema validation failed: {k}: Invalid type. Expected: object, given: {_type_name(cfg[k])}'
    for key in ('schema-map','type-map'):
        if key in cfg and any(not isinstance(k,str) or not isinstance(v,str) for k,v in cfg[key].items()):
            return f'config file {path}: schema validation failed: {key}: Invalid type. Expected: string values'
    if 'schemastore-path' in cfg and not isinstance(cfg['schemastore-path'],str):
        return f'config file {path}: schema validation failed: schemastore-path: Invalid type. Expected: string, given: {_type_name(cfg["schemastore-path"])}'
    v=cfg.get('validators',{})
    invalid=set(v)-{'csv','json','ini'}
    if invalid: return f"config file {path}: schema validation failed: validators: Additional property {sorted(invalid)[0]} is not allowed"
    for typ,opts in v.items():
        if not isinstance(opts,dict):
            kind='string' if isinstance(opts,str) else 'boolean' if isinstance(opts,bool) else 'integer' if isinstance(opts,int) else 'array' if isinstance(opts,list) else 'number' if isinstance(opts,float) else 'object'
            return f'config file {path}: schema validation failed: validators.{typ}: Invalid type. Expected: object, given: {kind}'
        allowed={'csv':{'delimiter','comment','lazy-quotes'},'json':{'forbid-duplicate-keys'},'ini':{'forbid-duplicate-keys'}}.get(typ,set())
        extras=set(opts)-allowed
        if extras: return f'config file {path}: schema validation failed: validators.{typ}: Additional property {sorted(extras)[0]} is not allowed'
        expected={
            'csv':{'delimiter':str,'comment':str,'lazy-quotes':bool},
            'json':{'forbid-duplicate-keys':bool},
            'ini':{'forbid-duplicate-keys':bool},
        }[typ]
        for opt,value in opts.items():
            if opt in expected and not isinstance(value,expected[opt]):
                kind='string' if isinstance(value,str) else 'boolean' if isinstance(value,bool) else 'integer' if isinstance(value,int) else 'array' if isinstance(value,list) else 'number' if isinstance(value,float) else 'object'
                expected_name='string' if expected[opt] is str else 'boolean'
                return f'config file {path}: schema validation failed: validators.{typ}.{opt}: Invalid type. Expected: {expected_name}, given: {kind}'
        if typ=='csv' and isinstance(opts.get('delimiter'),str) and len(opts['delimiter'])>2:
            return f'config file {path}: schema validation failed: validators.csv.delimiter: String length must be less than or equal to 2'
    return None
